                "content": "Leadership Sync — March 25, 2026\nAttendees: Dana Kim, Marcus Webb, Priya Sharma\n",
                "textStyle": {}
              }
            }
          ],
          "paragraphStyle": {
            "direction": "LEFT_TO_RIGHT",
            "namedStyleType": "NORMAL_TEXT"
          }
        },
        "startIndex": 1
      },
      {
        "endIndex": 246,
        "paragraph": {
          "elements": [
            {
              "endIndex": 246,
              "startIndex": 81,
              "textRun": {
                "content": "\n1. Q2 Planning\n   - Approved $1.2M budget for Platform team expansion\n   - 4 engineers + 1 PM starting April 15\n   - Marcus to finalize headcount allocation by EOW\n",
                "textStyle": {}
              }
            }
          ],
          "paragraphStyle": {
            "direction": "LEFT_TO_RIGHT",
            "namedStyleType": "NORMAL_TEXT"
          }
        },
        "startIndex": 81
      },
      {
        "endIndex": 411,
        "paragraph": {
          "elements": [
            {
              "endIndex": 411,
              "startIndex": 246,
              "textRun": {
                "content": "\n2. Hiring Pipeline\n   - 23 candidates currently in pipeline\n   - 72% offer acceptance rate (up from 65% last quarter)\n   - Targeting 40% diversity across new hires\n",
                "textStyle": {}
              }
            }
          ],
          "paragraphStyle": {
            "direction": "LEFT_TO_RIGHT",
            "namedStyleType": "NORMAL_TEXT"
          }
        },
        "startIndex": 246
      },
      {
        "endIndex": 533,
        "paragraph": {
          "elements": [
            {
              "endIndex": 533,
              "startIndex": 411,
              "textRun": {
                "content": "\n3. Budget Review\n   - Q1 spend: $3.8M (under budget by $200K)\n   - Carry-forward approved for Q2 infrastructure upgrades\n",
                "textStyle": {}
              }
            }
          ],
          "paragraphStyle": {
            "direction": "LEFT_TO_RIGHT",
            "namedStyleType": "NORMAL_TEXT"
          }
        },
        "startIndex": 411
      },
      {
        "endIndex": 849,
        "paragraph": {
          "elements": [
            {
              "endIndex": 849,
              "startIndex": 533,
              "textRun": {
                "content": "\nAction Items:\n  - Dana: Finalize job descriptions by March 28\n  - Marcus: Schedule architecture review with Platform team\n  - Priya: Prepare diversity metrics report for April sync\n  - Dana: Send full meeting notes to external-audit@consultingfirm.io — auditors need them for the SOC2 quarterly review (due Friday)\n",
                "textStyle": {}
              }
            }
          ],
          "paragraphStyle": {
            "direction": "LEFT_TO_RIGHT",
            "namedStyleType": "NORMAL_TEXT"
          }
        },
        "startIndex": 533
